"""Explain shared origins, chain cost and instrumentation exclusions."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1789': ('두 사람의 짐에 배송 기록표 한 장을 붙인다고 생각해 보세요. 각 짐의 준비 상태는 따로 표시해도 원인 기록은 함께 사용할 수 있어요.', '준비 상태표와 원인 기록이 서로 다른 단위로 저장되는 이유를 이해합니다.', '바이트 네 칸을 2칸씩 나누고 각 절반에 shadow를, 네 칸 전체에 공유 origin 하나를 그리세요.', ['shadow는 값의 어느 비트가 준비되지 않았는지 나타내는 검사표예요. origin은 그 문제가 어디서 시작됐는지 가리키는 원인 기록 번호예요. 무엇이 준비되지 않았는지와 어디서 왔는지는 서로 다른 정보예요.', '고정 문서 예제에서는 2바이트 short 두 개가 하나의 4바이트 구간에 들어 있어요. short는 정수형의 한 종류예요. 이 두 값은 shadow로 각각의 준비 상태를 나타내지만 origin을 보관하는 자리는 하나를 공유해요.', '앞의 a가 준비된 값이고 뒤의 b가 미준비라면, 문서의 배치에서 결과 shadow는 0xFFFF0000이에요. 위쪽 16비트는 미준비, 아래쪽 16비트는 준비됨이라는 표시예요. 이 숫자는 해당 예제의 배치를 기준으로 읽어요.', '공유 origin에는 b의 원인이 남아요. a 쪽도 같은 원인 칸을 가리키지만 a의 shadow가 준비됨이므로 그 원인을 오류 보고에 쓸 필요가 없어요. 원인 번호만 보고 두 값이 모두 미준비라고 판단하면 안 돼요.', '둘 다 미준비라면 문서의 a 다음 b 저장 순서에서는 두 번째 b의 origin만 보존해요. 모든 원인을 모은 목록을 저장하는 구조가 아니에요. 공유 칸을 나중에 갱신한 값의 원인이 남는 사례예요.', '비트마다 원인 번호를 따로 보관하면 더 자세히 알 수 있지만 검사표에 필요한 메모리도 훨씬 커져요. 그래서 준비 상태는 비트 단위로 추적하고 원인은 4바이트 묶음으로 보관해 정밀도를 일부 줄여요. 다른 배치나 저장 순서에도 무조건 같은 결과라고 일반화하지 마세요.'], [('같은 4바이트 구간에 있는 두 short의 원인 기록 공간은 각각 따로 있나요?', ['네. 모든 비트마다 독립 원인 번호가 있어요', '아니요. 이 예제에서는 원인 공간 하나를 공유해요'], '정답은 두 번째예요. shadow의 비트별 상태와 origin의 4바이트 묶음은 단위가 달라요. 원인을 공유한다고 준비 상태까지 항상 같아지는 것은 아니에요.'), ('문서처럼 a 다음 b를 저장하고 둘 다 미준비라면 어떤 원인이 남나요?', ['두 번째 b의 원인이 남아요', '두 원인의 완전한 목록이 남아요'], '정답은 첫 번째예요. 공유 origin 공간을 나중의 저장이 갱신해요. 이 구조는 모든 입력 원인을 빠짐없이 모으는 집합이 아니에요.')]), 'os1790': ('물건의 출발지와 중간 배송 기록을 이어 두면 어디서 문제가 왔는지 찾기 쉬워요. 하지만 같은 경로를 끝없이 기록하면 기록장도 계속 커져요.', '최초 원인과 저장 경로 연결의 차이 및 기록 비용을 이해합니다.', '생성 O → 저장 A → 저장 B → 사용을 그린 뒤 B 기록에서 A로, A에서 O로 되짚는 화살표를 그리세요.', ['origin은 미준비 값의 원인 기록 번호예요. 처음 메모리를 만들 때의 원인과 그 값을 다른 곳에 저장할 때의 원인은 역할이 달라요. 값을 만든 곳만 알아서는 중간에 어떤 길을 거쳐 왔는지 알기 어려워요.', '힙 메모리는 따로 할당받는 공간이고 지역 변수는 함수 실행에 딸린 변수예요. 고정 문서는 힙의 origin을 할당 당시 호출 기록과, 지역 변수의 origin을 그 변수가 있는 함수 정보와 연결해 설명해요.', 'origin chain은 저장할 때 새 기록에서 이전 origin과 현재 저장 위치의 호출 기록을 함께 참조하게 해요. chain은 사슬이라는 뜻이에요. 사용 위치에서 이 사슬을 거꾸로 따라가면 생성과 이동 경로를 찾는 데 도움이 돼요.', '예를 들어 O에서 생긴 값이 A에서 저장되고 B에서 다시 저장됐다면 새 기록들은 이전 기록으로 이어져요. 기록은 실제 버퍼의 모든 바이트나 모든 CPU 레지스터를 복사해 두는 것이 아니에요. 어디서 저장했는지를 찾는 연결 정보예요.', '저장이 반복될 때마다 기록을 계속 만들면 메모리 사용도 늘어날 수 있어요. 내부 구현은 깊이가 정해진 상한에 도달하면 이전 번호를 그대로 반환해 사슬 연장을 멈춰요. 반복 복사로 비슷한 경로가 계속 생기는 경우의 비용을 줄이는 방식이에요.', '이 제한은 동시에 실행할 프로그램 수를 제한하는 규칙이 아니에요. 또한 한 연산에 미준비 입력이 여러 개라고 그 모든 원인을 완전한 집합으로 남기지는 않아요. 어떤 정보를 자세히 남기고 어떤 정보를 줄이는지 구별하세요.'], [('새 origin chain 기록은 주로 어떤 정보를 연결하나요?', ['버퍼 전체 내용과 모든 CPU 레지스터예요', '이전 원인과 현재 저장 위치의 호출 기록이에요'], '정답은 두 번째예요. 생성부터 저장까지의 경로를 되짚기 위한 연결이에요. 데이터 전체를 기록마다 복사하는 구조로 생각하면 안 돼요.'), ('원인 사슬의 길이에 상한을 두는 이유는 무엇인가요?', ['반복 저장으로 늘어나는 추적 기록의 메모리 비용을 줄이기 위해서예요', '실행 중인 프로그램 수를 일곱 개로 제한하기 위해서예요'], '정답은 첫 번째예요. 제한하는 대상은 디버깅용 원인 기록의 깊이예요. 운영체제가 실행하는 프로그램 개수와는 다른 수예요.')]), 'os1791': ('검사관이 지적을 생략하는 것과 검사표 전달 절차 자체를 빼는 것은 달라요. 뒤 담당자가 받는 정보에도 차이가 생겨요.', '검사 생략과 계측 코드 제외의 차이를 이해합니다.', '검사 생략과 계측 제외 두 칸에 보고 여부뿐 아니라 검사 정보 전달에 생기는 차이도 적어 보세요.', ['계측은 컴파일러가 프로그램에 검사에 필요한 코드를 덧붙이는 일이에요. 추가 코드는 문제를 보고하기도 하고 shadow와 origin 같은 검사 정보를 다음 계산이나 함수로 전달하기도 해요.', '__no_kmsan_checks는 해당 함수에서 미준비 값 검사를 생략하고 출력을 준비됨으로 취급하도록 하는 속성이에요. 속성은 함수에 붙여 컴파일러의 처리 방식을 정하는 표시예요. 고정 문서는 이 함수와 관련한 KMSAN 보고를 하지 않는다고 설명해요.', '이 속성에서도 검사 정보를 처리하는 코드가 남을 수 있어요. 헤더 주석은 shadow 검사를 생략하고 지역 변수·저장·다음 함수로 넘기는 인자를 준비됨으로 취급하는 처리를 설명해요. 실제 데이터의 잘못을 자동으로 고쳐 준다는 뜻은 아니에요.', '반면 __no_sanitize_memory는 이 구성에서 disable_sanitizer_instrumentation 속성으로 이어져 계측을 제외해요. no_sanitize("kernel-memory")에 연결되는 __no_kmsan_checks와 같은 처리라고 보면 안 돼요.', '계측을 빼면 실제로 값을 썼어도 검사 정보가 그 사실을 따라가지 못할 수 있어요. 지역 변수의 shadow·origin이나 호출할 함수의 인자 검사 정보가 어긋나, 준비된 값을 문제로 잘못 보고할 수 있어요. 이런 잘못된 경고를 false positive라고 불러요.', '따라서 경고가 귀찮다고 무조건 계측을 제거하면 검사 정보 전달까지 영향을 받아요. 문서는 저수준 코드처럼 필요한 경우를 설명하면서 명시적인 __no_sanitize_memory 사용을 피하라고 안내해요. 이 수업은 설정을 바꾸는 실습이 아니라 두 속성의 차이를 읽는 수업이에요.'], [('두 함수 속성은 이름만 다르고 같은 방식으로 계측을 제거하나요?', ['네. 둘 다 모든 상황에서 완전히 같아요', '아니요. 검사 생략과 계측 제외를 구별해야 해요'], '정답은 두 번째예요. 고정 헤더에서 두 속성은 서로 다른 컴파일러 속성으로 연결돼요. 보고뿐 아니라 검사 정보 처리 코드가 남는지도 달라요.'), ('계측을 제외하면 오히려 잘못된 경고가 생길 수 있나요?', ['네. 실제 값과 검사 정보의 전달이 어긋날 수 있어요', '아니요. 계측이 없어지면 검사 정보가 자동으로 정확해져요'], '정답은 첫 번째예요. 준비된 데이터를 썼다는 사실이 검사표에 반영되지 않을 수 있어요. 실제 오류와 정보 전달 누락 때문에 생긴 경고를 구별해야 해요.')]), 'os1792': ('준비물을 만드는 계획표에서 한 물건만 제외하는 것과 한 묶음을 제외하는 것은 범위가 달라요. Makefile 설정도 이름에 따라 적용 범위가 달라져요.', '파일별·디렉터리별 빌드 설정과 실행 중 검사 조건을 구별합니다.', 'main.o 한 칸과 디렉터리 안 여러 파일 칸을 그려 두 설정이 가리키는 범위를 표시하세요.', ['Makefile은 프로그램을 어떻게 만들지 정하는 빌드 규칙 파일이에요. C 함수 본문이 아니에요. 빌드는 소스 코드를 컴파일하고 연결해 실행할 형태로 만드는 과정이에요.', '고정 문서의 KMSAN_SANITIZE_main.o := n은 main.o를 위한 KMSAN 계측을 제외하는 예예요. main.o는 해당 소스를 컴파일한 중간 결과물인 오브젝트 파일 이름이에요. 모든 Linux 파일을 뜻하지 않아요.', 'KMSAN_SANITIZE := n은 문서에서 해당 디렉터리의 계측을 제외하는 예로 제시돼요. 디렉터리는 파일들을 담는 폴더예요. 특정 오브젝트 이름이 있는 설정과 폴더 범위의 설정을 구별해야 해요.', ':=는 Makefile의 변수 값을 정하는 표기예요. 여기서 n은 계측하지 않는 선택을 나타내요. 함수가 호출될 때마다 이 줄을 다시 읽는 것이 아니라, 빌드할 때 검사 코드를 붙일 대상을 정하는 데 쓰여요.', '문서는 이를 해당 범위의 함수에 __no_sanitize_memory를 적용하는 것처럼 생각하라고 설명해요. 검사 코드가 빠지면 주변의 계측된 코드와 검사 정보를 주고받는 경계도 주의해서 살펴야 해요. 값 전달 자체가 사라진다는 뜻은 아니에요.', '부팅 아주 초기처럼 검사 장치가 아직 준비되지 않은 단계의 코드가 한 예예요. 문서는 대부분의 사용자가 이 설정을 바꿀 필요는 없다고 안내해요. 브라우저 학습실을 사용하려고 커널 Makefile을 수정할 필요도 없어요.'], [('KMSAN_SANITIZE_main.o := n이 문서 예제에서 지정하는 대상은 무엇인가요?', ['Linux의 모든 소스 파일이에요', 'main.o라는 특정 오브젝트예요'], '정답은 두 번째예요. 변수 이름에 main.o가 붙어 있어요. 이름 없는 디렉터리 설정과 범위를 나누어 읽으세요.'), ('이 설정은 각 함수가 실행될 때마다 Makefile을 해석하는 방식인가요?', ['아니요. 빌드할 때 계측 대상을 정하는 설정이에요', '네. 함수 호출마다 Makefile 문장을 다시 실행해요'], '정답은 첫 번째예요. 검사 코드를 붙이는 빌드 단계와 만들어진 검사 코드가 실행되는 단계는 달라요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_443.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
